// QA independent check for S-3 (not a committed test). Chromium only, against vite preview on :4173.
import { createRequire } from 'node:module';
const require = createRequire('/home/user/Web-Calculator-fresh/sabee-khan-calculator/package.json');
const { chromium } = require('@playwright/test');
const { AxeBuilder } = require('@axe-core/playwright');

const URL = 'http://127.0.0.1:4173/';
const M1 = 'Enter marks earned and total marks possible to see the score.';
const M2 = 'Enter a pass mark to see whether this is a pass or a fail.';
const M3 = 'The score will appear once every entry is valid.';
const MSG = {
  earned: { NAN: 'Marks earned must be a number, like 17.5.', NEG: "Marks earned can't be negative.", DP: 'Marks earned can have at most 2 decimal places.', OVER: "Marks earned can't be more than the total marks possible." },
  total: { NAN: 'Total marks possible must be a number, like 23.', NEG: "Total marks possible can't be negative.", DP: 'Total marks possible can have at most 2 decimal places.', ZERO: 'Total marks possible must be more than 0.', BIG: "Total marks possible can't be more than 1,000,000." },
  pass: { NAN: 'Pass mark must be a number, like 70.', NEG: "Pass mark can't be negative.", DP: 'Pass mark can have at most 1 decimal place.', BIG: "Pass mark can't be more than 100." },
};
const SEL = { earned: '#earned', total: '#total', pass: '#pass-mark' };

const browser = await chromium.launch();
const ctx = await browser.newContext({ viewport: { width: 1280, height: 900 }, permissions: ['clipboard-read', 'clipboard-write'] });
const page = await ctx.newPage();
const consoleProblems = [];
page.on('console', (m) => { if (m.type() === 'error' || m.type() === 'warning') consoleProblems.push(`${m.type()}: ${m.text()}`); });
page.on('pageerror', (e) => consoleProblems.push(`pageerror: ${e.message}`));

const rows = []; // {id, input, expected, observed, pass}
let fails = 0;
function record(id, input, expected, observed, ok) {
  rows.push({ id, input, expected, observed, ok });
  if (!ok) fails += 1;
}

async function snap() {
  return page.evaluate((SEL) => {
    const out = {};
    for (const [f, s] of Object.entries(SEL)) {
      const i = document.querySelector(s);
      const d = document.getElementById(i.getAttribute('aria-describedby'));
      out[f] = { value: i.value, invalid: i.getAttribute('aria-invalid'), err: d ? d.textContent.trim() : '<no describedby target>' };
    }
    const body = document.querySelector('.result-body');
    out.result = body.textContent.replace(/\s+/g, ' ').trim();
    out.score = document.querySelector('.score')?.textContent ?? null;
    out.verdict = document.querySelector('.verdict')?.textContent.trim() ?? null;
    out.gap = document.querySelector('.gap')?.textContent.trim() ?? null;
    out.all = document.querySelector('.card').innerText;
    return out;
  }, SEL);
}

async function typeField(field, text) {
  const loc = page.locator(SEL[field]);
  await loc.click();
  await page.keyboard.press('ControlOrMeta+a');
  await page.keyboard.press('Delete');
  if (text.length > 0) await page.keyboard.type(text);
}
async function setAll(e, t, p) { await typeField('pass', p); await typeField('total', t); await typeField('earned', e); }

function bad(s) { return /NaN|Infinity|undefined/.test(s.all) || s.result === ''; }
function fmtErr(s) {
  return ['earned', 'total', 'pass'].map((f) => `${f}:${s[f].err ? `"${s[f].err}"` : '—'}${s[f].invalid === 'true' ? '[inv]' : ''}`).join(' ');
}
function describe(s) {
  const parts = [fmtErr(s)];
  if (s.score) parts.push(`score ${s.score}`);
  if (s.verdict) parts.push(s.verdict);
  if (s.gap) parts.push(`gap "${s.gap}"`);
  if (!s.score) parts.push(`result "${s.result}"`);
  else if (s.result.includes(M2)) parts.push('M-2');
  return parts.join('; ');
}

/** expectation: {errors:{field:text}, score?:string|null, resultHas?:string} */
function check(id, input, s, exp) {
  const errs = exp.errors ?? {};
  let ok = !bad(s);
  for (const f of ['earned', 'total', 'pass']) {
    const want = errs[f] ?? '';
    if (s[f].err !== want) ok = false;
    if ((want !== '') !== (s[f].invalid === 'true')) ok = false;
  }
  const anyErr = Object.keys(errs).length > 0;
  if (anyErr) {
    if (s.score || s.verdict || s.gap) ok = false;
    if (!s.result.includes(M3)) ok = false;
    if (s.result.includes(M1)) ok = false;
  }
  if (exp.score !== undefined && s.score !== exp.score) ok = false;
  if (exp.resultHas && !s.result.includes(exp.resultHas)) ok = false;
  if (exp.verdict !== undefined && s.verdict !== exp.verdict) ok = false;
  if (exp.gap !== undefined && s.gap !== exp.gap) ok = false;
  const expected = [
    anyErr ? Object.entries(errs).map(([f, t]) => `${f}:"${t}"`).join(' ') + ' + M-3' : 'no field error',
    exp.score !== undefined ? `score ${exp.score}` : '',
    exp.resultHas === M1 ? 'M-1' : exp.resultHas === M2 ? 'M-2' : '',
    exp.verdict ? exp.verdict : '',
    exp.gap ? `gap "${exp.gap}"` : '',
  ].filter(Boolean).join('; ');
  record(id, input, expected, describe(s), ok);
}

await page.goto(URL);

// ---------------- AC examples ----------------
// S-3.1
await typeField('earned', '17.5');
check('S-3.1', 'earned "17.5" only', await snap(), { resultHas: M1, score: null });
await page.reload();
await typeField('total', '   ');
check('S-3.1', 'total "   " only', await snap(), { resultHas: M1, score: null });
// S-3.2
await page.reload();
await setAll('17.5', '23', '70');
await typeField('pass', '');
check('S-3.2', '17.5 / 23, pass cleared', await snap(), { score: '76.0%', resultHas: M2, verdict: null, gap: null });
// S-3.3
await page.reload();
await setAll('', '23', '70');
for (const v of ['abc', '17,5', '$17', '1.2.3', '1e400', '+5']) {
  await typeField('earned', v);
  check('S-3.3', `earned "${v}"`, await snap(), { errors: { earned: MSG.earned.NAN } });
}
await typeField('earned', '17.5'); await typeField('total', 'abc');
check('S-3.3', 'total "abc"', await snap(), { errors: { total: MSG.total.NAN } });
await typeField('total', '23'); await typeField('pass', 'seventy');
check('S-3.3', 'pass "seventy"', await snap(), { errors: { pass: MSG.pass.NAN } });
await typeField('pass', '70'); await typeField('earned', ' 017.5 ');
check('S-3.3', 'earned " 017.5 "', await snap(), { score: '76.0%', verdict: 'Pass' });
// S-3.4
for (const v of ['-1', '-0']) { await typeField('earned', v); check('S-3.4', `earned "${v}"`, await snap(), { errors: { earned: MSG.earned.NEG } }); }
await typeField('earned', '17.5'); await typeField('total', '-23');
check('S-3.4', 'total "-23"', await snap(), { errors: { total: MSG.total.NEG } });
await typeField('total', '23'); await typeField('pass', '-5');
check('S-3.4', 'pass "-5"', await snap(), { errors: { pass: MSG.pass.NEG } });
// S-3.5
await typeField('pass', '70'); await typeField('earned', '17.555');
check('S-3.5', 'earned "17.555"', await snap(), { errors: { earned: MSG.earned.DP } });
await typeField('earned', '17.5'); await typeField('total', '23.001');
check('S-3.5', 'total "23.001"', await snap(), { errors: { total: MSG.total.DP } });
await typeField('total', '23'); await typeField('pass', '70.05');
check('S-3.5', 'pass "70.05"', await snap(), { errors: { pass: MSG.pass.DP } });
// S-3.6
await setAll('10', '0', '70');
check('S-3.6', 'earned 10, total "0"', await snap(), { errors: { total: MSG.total.ZERO } });
await typeField('total', '1000000.01');
check('S-3.6', 'total "1000000.01"', await snap(), { errors: { total: MSG.total.BIG } });
await typeField('total', '8');
check('S-3.6', 'total "8"', await snap(), { errors: { earned: MSG.earned.OVER } });
await typeField('total', '23'); await typeField('pass', '100.1');
check('S-3.6', 'pass "100.1" (total 23)', await snap(), { errors: { pass: MSG.pass.BIG } });
await typeField('pass', '70'); await typeField('total', '1000000');
check('S-3.6', 'total "1000000"', await snap(), { score: '0.0%', verdict: 'Fail' });
// S-3.7
await page.reload();
await setAll('abc', '0', '70');
check('S-3.7', 'earned "abc" + total "0"', await snap(), { errors: { earned: MSG.earned.NAN, total: MSG.total.ZERO } });
await page.waitForTimeout(900);
const statusText = await page.locator('[role=status]').textContent();
record('S-3.7', 'status (aria-live) after debounce', `"${MSG.earned.NAN} ${MSG.total.ZERO} ${M3}"`, `"${statusText}"`, statusText === `${MSG.earned.NAN} ${MSG.total.ZERO} ${M3}`);
// S-3.8
await page.reload();
await setAll('23.5', '23', '70');
check('S-3.8', '23.5 of 23', await snap(), { errors: { earned: MSG.earned.OVER } });
await typeField('earned', '17.5');
check('S-3.8', 'earned → 17.5', await snap(), { score: '76.0%', verdict: 'Pass', gap: '1.4 marks above the pass mark' });
await page.reload();
await setAll('23.5', '23', '70');
await typeField('total', '25');
check('S-3.8', 'total → 25', await snap(), { score: '94.0%', verdict: 'Pass', gap: '6 marks above the pass mark' });

const acRows = rows.length;

// ---------------- Edge sweep per field ----------------
// Base: earned 17.5, total 23, pass 70 → 76.0%, Pass.
const long400 = '9'.repeat(400);
const longFrac = '0.' + '1'.repeat(400);
const E = 'earned', T = 'total', P = 'pass';
const cases = [
  // [field, input, expectation]
  [E, '', { resultHas: M1, score: null }], [T, '', { resultHas: M1, score: null }], [P, '', { score: '76.0%', resultHas: M2, verdict: null }],
  [E, '    ', { resultHas: M1, score: null }], [T, '    ', { resultHas: M1, score: null }], [P, '    ', { score: '76.0%', resultHas: M2, verdict: null }],
  ...['abc', '$17', '€17', '17%', '+5', '1e400', '1..2', '..', '17 .5', '- 5', '--5', 'Infinity', 'NaN', '0x10', '１７', '1,000'].flatMap((v) => [
    [E, v, { errors: { earned: MSG.earned.NAN } }], [T, v, { errors: { total: MSG.total.NAN } }], [P, v, { errors: { pass: MSG.pass.NAN } }],
  ]),
  ...['-0', '-', '-.', '-5', '-17.555', ' -5 '].flatMap((v) => [
    [E, v, { errors: { earned: MSG.earned.NEG } }], [T, v, { errors: { total: MSG.total.NEG } }], [P, v, { errors: { pass: MSG.pass.NEG } }],
  ]),
  [E, '.', { resultHas: M1, score: null }], [T, '.', { resultHas: M1, score: null }], [P, '.', { score: '76.0%', resultHas: M2, verdict: null }],
  [E, '5.', { score: '21.7%', verdict: 'Fail' }], [T, '25.', { score: '70.0%', verdict: 'Pass' }], [P, '80.', { score: '76.0%', verdict: 'Fail' }],
  [E, '.5', { score: '2.2%', verdict: 'Fail' }], [T, '.5', { errors: { earned: MSG.earned.OVER } }], [P, '.5', { score: '76.0%', verdict: 'Pass' }],
  [E, '0017.5', { score: '76.0%', verdict: 'Pass' }], [T, '0023', { score: '76.0%', verdict: 'Pass' }], [P, '070', { score: '76.0%', verdict: 'Pass' }],
  [E, '0', { score: '0.0%', verdict: 'Fail' }], [T, '0', { errors: { total: MSG.total.ZERO } }], [P, '0', { score: '76.0%', verdict: 'Pass' }],
  [T, '0.00', { errors: { total: MSG.total.ZERO } }], [T, '0.01', { errors: { earned: MSG.earned.OVER } }],
  [T, '1000000', { score: '0.0%', verdict: 'Fail' }], [P, '100', { score: '76.0%', verdict: 'Fail' }], [E, '23', { score: '100.0%', verdict: 'Pass' }],
  [T, '1000000.01', { errors: { total: MSG.total.BIG } }], [P, '100.1', { errors: { pass: MSG.pass.BIG } }], [E, '23.01', { errors: { earned: MSG.earned.OVER } }],
  [E, '17.555', { errors: { earned: MSG.earned.DP } }], [T, '23.001', { errors: { total: MSG.total.DP } }], [P, '70.05', { errors: { pass: MSG.pass.DP } }],
  [E, '17.500', { errors: { earned: MSG.earned.DP } }], [T, '23.000', { errors: { total: MSG.total.DP } }], [P, '70.00', { errors: { pass: MSG.pass.DP } }],
  [E, '17.50', { score: '76.0%', verdict: 'Pass' }], [P, '70.0', { score: '76.0%', verdict: 'Pass' }],
  [E, long400, { errors: { earned: MSG.earned.OVER } }], [T, long400, { errors: { total: MSG.total.BIG } }], [P, long400, { errors: { pass: MSG.pass.BIG } }],
  [E, longFrac, { errors: { earned: MSG.earned.DP } }], [T, longFrac, { errors: { total: MSG.total.DP } }], [P, longFrac, { errors: { pass: MSG.pass.DP } }],
  [E, '0'.repeat(400) + '17.5', { score: '76.0%', verdict: 'Pass' }],
];
for (const [field, v, exp] of cases) {
  await page.goto(URL);
  await setAll('17.5', '23', '70');
  await typeField(field, v);
  const shown = v.length > 30 ? `${v.slice(0, 12)}…(${v.length} chars)` : JSON.stringify(v);
  check('edge', `${field} ${shown}`, await snap(), exp);
}

// Pasted values (real clipboard paste, Ctrl+V)
const pastes = [
  [E, ' 17.5 ', { score: '76.0%', verdict: 'Pass' }],
  [E, '17.5\t', { score: '76.0%', verdict: 'Pass' }],
  [E, '$17', { errors: { earned: MSG.earned.NAN } }],
  [T, '£23', { errors: { total: MSG.total.NAN } }],
  [T, ' 23 ', { score: '76.0%', verdict: 'Pass' }],
  [P, '70 %', { errors: { pass: MSG.pass.NAN } }],
  [P, ' 70 ', { score: '76.0%', verdict: 'Pass' }],
  [E, '17.5\n', { score: '76.0%', verdict: 'Pass' }],
];
for (const [field, v, exp] of pastes) {
  await page.goto(URL);
  await setAll('17.5', '23', '70');
  await page.evaluate((t) => navigator.clipboard.writeText(t), v);
  await page.locator(SEL[field]).click();
  await page.keyboard.press('ControlOrMeta+a');
  await page.keyboard.press('ControlOrMeta+v');
  const s = await snap();
  check('paste', `${field} paste ${JSON.stringify(v)} (field value ${JSON.stringify(s[field].value)})`, s, exp);
}

// Mid-number typing never flashes an error (rapid typing, snapshot after each key)
for (const [field, text] of [[E, '17.5'], [E, '.5'], [T, '23.25'], [P, '62.5']]) {
  await page.goto(URL);
  await setAll('17.5', '23', '70');
  await typeField(field, '');
  let flashes = [];
  for (const ch of text) {
    await page.keyboard.type(ch);
    const s = await snap();
    if (s[field].err !== '' || bad(s)) flashes.push(`${s[field].value}→${s[field].err || 'blank/NaN'}`);
  }
  record('typing', `${field} typed "${text}" key by key`, 'no error at any keystroke', flashes.length ? flashes.join(', ') : 'no error at any keystroke', flashes.length === 0);
}
// Rapid typing (no delay) then immediate snapshot
await page.goto(URL);
await setAll('', '', '70');
await page.locator('#earned').click(); await page.keyboard.type('17.5', { delay: 0 });
await page.locator('#total').click(); await page.keyboard.type('23', { delay: 0 });
check('typing', 'rapid typing 17.5 / 23 (delay 0)', await snap(), { score: '76.0%', verdict: 'Pass' });

// Repeated Enter in each field while in error state
await page.goto(URL);
await setAll('abc', '0', '100.1');
for (const f of [E, T, P]) { await page.locator(SEL[f]).click(); for (let i = 0; i < 5; i++) await page.keyboard.press('Enter'); }
{
  const s = await snap();
  const okVals = s.earned.value === 'abc' && s.total.value === '0' && s.pass.value === '100.1';
  check('enter', 'Enter ×5 in each field, three errors (values kept: ' + okVals + ', url ' + page.url() + ')', s, { errors: { earned: MSG.earned.NAN, total: MSG.total.ZERO, pass: MSG.pass.BIG } });
  if (!okVals || page.url() !== URL) record('enter', 'values/url after Enter', 'unchanged', JSON.stringify([s.earned.value, s.total.value, s.pass.value, page.url()]), false);
}
await page.goto(URL);
await setAll('17.5', '23', '70');
for (const f of [E, T, P]) { await page.locator(SEL[f]).click(); for (let i = 0; i < 5; i++) await page.keyboard.press('Enter'); }
check('enter', 'Enter ×5 in each field, valid result', await snap(), { score: '76.0%', verdict: 'Pass', gap: '1.4 marks above the pass mark' });

// Multiple simultaneous errors and recovery
await page.goto(URL);
await setAll('abc', '0', '100.1');
check('multi', 'three errors: earned abc, total 0, pass 100.1', await snap(), { errors: { earned: MSG.earned.NAN, total: MSG.total.ZERO, pass: MSG.pass.BIG } });
await typeField(E, '17.5');
check('recover', '…fix earned → 17.5', await snap(), { errors: { total: MSG.total.ZERO, pass: MSG.pass.BIG } });
await typeField(T, '23');
check('recover', '…fix total → 23', await snap(), { errors: { pass: MSG.pass.BIG } });
await typeField(P, '70');
check('recover', '…fix pass → 70', await snap(), { score: '76.0%', verdict: 'Pass', gap: '1.4 marks above the pass mark' });
await page.goto(URL);
await setAll('-17.555', '23.001', '-70.05');
check('multi', 'three errors in A-15 order: -17.555 / 23.001 / -70.05', await snap(), { errors: { earned: MSG.earned.NEG, total: MSG.total.DP, pass: MSG.pass.NEG } });
await page.goto(URL);
await setAll('abc', '', '70');
check('multi', 'earned abc, total empty → M-3 not M-1', await snap(), { errors: { earned: MSG.earned.NAN } });
await page.goto(URL);
await setAll('50', 'abc', '70');
check('multi', 'earned 50, total abc → only total error (M-15 not checked)', await snap(), { errors: { total: MSG.total.NAN } });

// Earned > total appearing/disappearing as total changes
await page.goto(URL);
await setAll('30', '23', '70');
check('over', 'earned 30, total 23', await snap(), { errors: { earned: MSG.earned.OVER } });
await typeField(T, '30');
check('over', '…total → 30', await snap(), { score: '100.0%', verdict: 'Pass' });
await typeField(T, '29.99');
check('over', '…total → 29.99', await snap(), { errors: { earned: MSG.earned.OVER } });
await typeField(T, '');
check('over', '…total → empty', await snap(), { resultHas: M1, score: null });
await typeField(T, '0');
check('over', '…total → 0 (M-19 only, no M-15)', await snap(), { errors: { total: MSG.total.ZERO } });
await typeField(T, '300');
check('over', '…total → 300', await snap(), { score: '10.0%', verdict: 'Fail' });
// Recovery after each single-field error type
for (const [field, badV, goodV] of [[E, 'abc', '17.5'], [E, '-1', '17.5'], [E, '17.555', '17.5'], [T, '-23', '23'], [T, '23.001', '23'], [T, '1000000.01', '23'], [P, 'seventy', '70'], [P, '-5', '70'], [P, '70.05', '70'], [P, '100.1', '70']]) {
  await page.goto(URL);
  await setAll('17.5', '23', '70');
  await typeField(field, badV);
  await typeField(field, goodV);
  check('recover', `${field} "${badV}" → "${goodV}"`, await snap(), { score: '76.0%', verdict: 'Pass', gap: '1.4 marks above the pass mark' });
}
// Backspace recovery: "17.555" → Backspace → "17.55"
await page.goto(URL);
await setAll('17.555', '23', '70');
await page.keyboard.press('Backspace');
check('recover', 'earned 17.555 + Backspace → 17.55', await snap(), { score: '76.3%', verdict: 'Pass' });

// Page reload in error state
await page.goto(URL);
await setAll('abc', '0', '100.1');
await page.reload();
{
  const s = await snap();
  const ok = s.earned.value === '' && s.total.value === '' && s.pass.value === '70';
  check('reload', `reload in 3-error state (values ${JSON.stringify([s.earned.value, s.total.value, s.pass.value])})`, s, { resultHas: M1, score: null });
  if (!ok) record('reload', 'values after reload', '"", "", "70"', JSON.stringify([s.earned.value, s.total.value, s.pass.value]), false);
}

// ---------------- axe in error states (light/dark) ----------------
const axeRows = [];
for (const scheme of ['light', 'dark']) {
  await page.emulateMedia({ colorScheme: scheme });
  for (const [name, vals] of [['single error (abc/23/70)', ['abc', '23', '70']], ['three errors (abc/0/100.1)', ['abc', '0', '100.1']], ['M-15 (23.5/23/70)', ['23.5', '23', '70']]]) {
    await page.goto(URL);
    await setAll(...vals);
    await page.waitForTimeout(700);
    const r = await new AxeBuilder({ page }).withTags(['wcag2a', 'wcag2aa', 'wcag21a', 'wcag21aa', 'wcag22aa']).analyze();
    axeRows.push({ scheme, name, violations: r.violations.map((v) => `${v.id} (${v.nodes.length})`) });
    if (r.violations.length) fails += 1;
  }
}
await page.emulateMedia({ colorScheme: 'light' });

// ---------------- layout shift ----------------
const layoutRows = [];
for (const width of [320, 375, 1280]) {
  await page.setViewportSize({ width, height: 900 });
  const states = [
    ['idle', null],
    ['result (17.5/23/70)', ['17.5', '23', '70']],
    ['pass empty', ['17.5', '23', '']],
    ['single error (abc/23/70)', ['abc', '23', '70']],
    ['M-15 (23.5/23/70)', ['23.5', '23', '70']],
    ['three errors (abc/0/100.1)', ['abc', '0', '100.1']],
    ['three longest msgs (23.5/1000000.01/70.05)', ['23.5', '1000000.01', '70.05']],
  ];
  const meas = [];
  for (const [name, vals] of states) {
    await page.goto(URL);
    if (vals) await setAll(...vals);
    const m = await page.evaluate(() => {
      const card = document.querySelector('.card').getBoundingClientRect();
      const btn = document.querySelector('.btn').getBoundingClientRect();
      return { h: Math.round(card.height * 10) / 10, by: Math.round(btn.y * 10) / 10, sw: document.documentElement.scrollWidth };
    });
    meas.push({ name, ...m });
  }
