const M3 = 'The score will appear once every entry is valid.';
const MSG = {
  earned: { NAN: 'Marks earned must be a number, like 17.5.', NEG: "Marks earned can't be negative.", DP: 'Marks earned can have at most 2 decimal places.', OVER: "Marks earned can't be more than the total marks possible." },
  total: { NAN: 'Total marks possible must be a number, like 23.', NEG: "Total marks possible can't be negative.", DP: 'Total marks possible can have at most 2 decimal places.', ZERO: 'Total marks possible must be more than 0.', BIG: "Total marks possible can't be more than 1,000,000." },
  pass: { NAN: 'Pass mark must be a number, like 70.', NEG: "Pass mark can't be negative.", DP: 'Pass mark can have at most 1 decimal place.', BIG: "Pass mark can't be more than 100." },
};
const SEL = { earned: '#earned', total: '#total', pass: '#pass-mark' };

const browser = await chromium.launch();
const ctx = await browser.newContext({ viewport: { width: 1280, height: 900 }, permissions: ['clipboard-read', 'clipboard-write'] });
const page = await ctx.newPage();
const consoleProblems = [];
page.on('console', (m) => { if (m.type() === 'error' || m.type() === 'warning') consoleProblems.push(`${m.type()}: ${m.text()}`); });
page.on('pageerror', (e) => consoleProblems.push(`pageerror: ${e.message}`));

const rows = []; // {id, input, expected, observed, pass}
let fails = 0;
function record(id, input, expected, observed, ok) {
  rows.push({ id, input, expected, observed, ok });
  if (!ok) fails += 1;
}

async function snap() {
  return page.evaluate((SEL) => {
    const out = {};
    for (const [f, s] of Object.entries(SEL)) {
      const i = document.querySelector(s);
      const d = document.getElementById(i.getAttribute('aria-describedby'));
      out[f] = { value: i.value, invalid: i.getAttribute('aria-invalid'), err: d ? d.textContent.trim() : '<no describedby target>' };
    }
    const body = document.querySelector('.result-body');
    out.result = body.textContent.replace(/\s+/g, ' ').trim();
    out.score = document.querySelector('.score')?.textContent ?? null;
    out.verdict = document.querySelector('.verdict')?.textContent.trim() ?? null;
    out.gap = document.querySelector('.gap')?.textContent.trim() ?? null;
    out.all = document.querySelector('.card').innerText;
    return out;
  }, SEL);
}

async function typeField(field, text) {
  const loc = page.locator(SEL[field]);
  await loc.click();
  await page.keyboard.press('ControlOrMeta+a');
  await page.keyboard.press('Delete');
  if (text.length > 0) await page.keyboard.type(text);
}
async function setAll(e, t, p) { await typeField('pass', p); await typeField('total', t); await typeField('earned', e); }

function bad(s) { return /NaN|Infinity|undefined/.test(s.all) || s.result === ''; }
function fmtErr(s) {
  return ['earned', 'total', 'pass'].map((f) => `${f}:${s[f].err ? `"${s[f].err}"` : '—'}${s[f].invalid === 'true' ? '[inv]' : ''}`).join(' ');
}
function describe(s) {
  const parts = [fmtErr(s)];
  if (s.score) parts.push(`score ${s.score}`);
  if (s.verdict) parts.push(s.verdict);
  if (s.gap) parts.push(`gap "${s.gap}"`);
  if (!s.score) parts.push(`result "${s.result}"`);
  else if (s.result.includes(M2)) parts.push('M-2');
  return parts.join('; ');
}

/** expectation: {errors:{field:text}, score?:string|null, resultHas?:string} */
function check(id, input, s, exp) {
  const errs = exp.errors ?? {};
  let ok = !bad(s);
  for (const f of ['earned', 'total', 'pass']) {
    const want = errs[f] ?? '';
    if (s[f].err !== want) ok = false;
    if ((want !== '') !== (s[f].invalid === 'true')) ok = false;
  }
  const anyErr = Object.keys(errs).length > 0;
  if (anyErr) {
    if (s.score || s.verdict || s.gap) ok = false;
    if (!s.result.includes(M3)) ok = false;
    if (s.result.includes(M1)) ok = false;
  }
  if (exp.score !== undefined && s.score !== exp.score) ok = false;
  if (exp.resultHas && !s.result.includes(exp.resultHas)) ok = false;
  if (exp.verdict !== undefined && s.verdict !== exp.verdict) ok = false;
  if (exp.gap !== undefined && s.gap !== exp.gap) ok = false;
  const expected = [
    anyErr ? Object.entries(errs).map(([f, t]) => `${f}:"${t}"`).join(' ') + ' + M-3' : 'no field error',
    exp.score !== undefined ? `score ${exp.score}` : '',
    exp.resultHas === M1 ? 'M-1' : exp.resultHas === M2 ? 'M-2' : '',
    exp.verdict ? exp.verdict : '',
    exp.gap ? `gap "${exp.gap}"` : '',
  ].filter(Boolean).join('; ');
  record(id, input, expected, describe(s), ok);
}

