      return { h: Math.round(card.height * 10) / 10, by: Math.round(btn.y * 10) / 10, sw: document.documentElement.scrollWidth };
    });
    meas.push({ name, ...m });
  }
  layoutRows.push({ width, meas });
  const hs = new Set(meas.map((m) => m.h)); const ys = new Set(meas.map((m) => m.by));
  if (hs.size > 1 || ys.size > 1 || meas.some((m) => m.sw > width)) fails += 1;
}

await browser.close();
console.log(JSON.stringify({ acRows, rows, axeRows, layoutRows, consoleProblems, fails }, null, 1));

